UPDATE tools SET faq = $x$[{"q": "Що таке Khanmigo?", "a": "Khanmigo — це ШІ-репетитор Khan Academy. Він працює на моделях OpenAI через Azure OpenAI Service від Microsoft, а Google Gemini забезпечує деякі новіші функції, наприклад інтерактивні діаграми. Він допомагає учням з академічними предметами, використовуючи метод Сократа — задаючи навідні запитання замість прямих відповідей. Він безкоштовний для вчителів, але доступ для окремих учнів та родин вимагає платної підписки."}, {"q": "Чи безкоштовний Khanmigo?", "a": "Khanmigo безкоштовний для вчителів, підписка не потрібна. Індивідуальний доступ для учнів та доступ для родин коштують по $4 на місяць або $44 на рік кожен, плюс податок з продажів. Деякі шкільні округи надають безкоштовний доступ учням до Khanmigo через угоди на рівні округу."}, {"q": "Чи може Duolingo навчити мене вільно володіти мовою?", "a": "Duolingo ефективно розбудовує словниковий запас та базову граматику, але зазвичай недостатній для досягнення вільного володіння самостійно. Найкраще він працює як щоденна звичка в поєднанні з іншою практикою, наприклад спілкуванням з носіями мови, переглядом контенту або використанням таких інструментів, як iTalki, для розмовної практики."}]$x$::jsonb
 WHERE slug = 'khanmigo' AND lang = 'ua';

